import { computeShrinkTarget, effectiveTransitionDuration, nextExperienceState, resolvePreset } from "../transition-engine.js";

const els = Object.fromEntries(["experience","profile","introLayer","mediaStage","avatarTarget","introVideo","skipButton","previewStart","progressBar","previewAvatar","previewName","previewHandle","previewPrimaryRole","previewSecondaryRoles","previewEducation","previewBio"].map(id => [id,document.getElementById(id)]));
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)");
let state = "profile"; let token = 0; let transitionTimer; let splitArmed;

function setState(event){ state=nextExperienceState(state,event); els.experience.dataset.state=state; els.profile.setAttribute("aria-hidden",String(state!=="profile")); document.body.classList.toggle("is-experiencing",state!=="profile"); }
function clearSplitVideos(){ els.mediaStage.querySelectorAll(".split-live-video").forEach(v=>{v.pause();v.removeAttribute("src");v.load();v.remove();}); }
function armSplitLiveVideo(sourceVideo){ clearSplitVideos(); const src=sourceVideo.currentSrc||sourceVideo.src; if(!src)return; const at=sourceVideo.currentTime; sourceVideo.pause(); els.mediaStage.querySelectorAll(".split-panel").forEach(panel=>{const clone=document.createElement("video");clone.className="split-live-video";clone.muted=true;clone.playsInline=true;clone.loop=true;clone.src=src;panel.appendChild(clone);clone.currentTime=at;clone.play().catch(()=>{});}); }
function finish(current){ if(current!==token)return; setState("TRANSITION_COMPLETE"); els.introLayer.style.visibility="hidden"; clearSplitVideos(); }
function begin(config,current){ if(current!==token||state!=="intro")return; if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} if(config.transitionKey==="split")armSplitLiveVideo(els.introVideo); if(config.transitionKey==="shrink"){els.profile.classList.add("measure-target");const target=computeShrinkTarget(els.introLayer.getBoundingClientRect(),els.avatarTarget.getBoundingClientRect());els.profile.classList.remove("measure-target");els.mediaStage.style.setProperty("--shrink-x",`${target.x}px`);els.mediaStage.style.setProperty("--shrink-y",`${target.y}px`);els.mediaStage.style.setProperty("--shrink-scale",target.scale);els.mediaStage.style.setProperty("--shrink-radius",`${target.clipRadius}px`);} setState("INTRO_COMPLETE");const duration=effectiveTransitionDuration(1400,reduceMotion.matches);els.experience.style.setProperty("--transition-ms",`${duration}ms`);transitionTimer=setTimeout(()=>finish(current),duration+60); }
function play(config){ clearTimeout(transitionTimer); if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} clearSplitVideos(); token+=1;const current=token;const preset=resolvePreset(config.transitionKey);els.introLayer.className=`intro-layer ${preset.className}`;els.experience.dataset.preset=config.transitionKey;els.introLayer.style.visibility="visible";els.previewAvatar.src=config.avatarUrl||"";els.previewName.textContent=config.displayName||"Gamer";els.previewHandle.textContent=config.handle||"@handle";els.previewPrimaryRole.textContent=config.primaryRole||"";els.previewSecondaryRoles.textContent=(config.secondaryRoles||[]).join(" · ");els.previewEducation.textContent=config.education||"";els.previewBio.textContent=config.bio||"";els.introVideo.src=config.videoUrl;state="profile";setState("REPLAY");els.introVideo.currentTime=0;els.previewStart.hidden=true;const start=()=>els.introVideo.play().then(()=>{els.previewStart.hidden=true;}).catch(()=>{els.previewStart.hidden=false;});start();els.previewStart.onclick=start;els.introVideo.onended=()=>begin(config,current);els.introVideo.onerror=()=>parent.postMessage({type:"gamid-intro-preview-error"},location.origin);if(config.transitionKey==="split"&&!reduceMotion.matches){const threshold=effectiveTransitionDuration(1400,reduceMotion.matches)/1000;splitArmed=()=>{if(els.introVideo.duration&&els.introVideo.duration-els.introVideo.currentTime<=threshold)begin(config,current);};els.introVideo.addEventListener("timeupdate",splitArmed);} }
els.skipButton.addEventListener("click",()=>{token+=1;clearTimeout(transitionTimer);if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;}els.introVideo.pause();state="intro";setState("SKIP");els.introLayer.style.visibility="hidden";clearSplitVideos();});
addEventListener("message",event=>{if(event.origin!==location.origin||event.data?.type!=="gamid-intro-preview")return;play(event.data.config);});
parent.postMessage({type:"gamid-intro-preview-ready"},location.origin);
